summary:
bash: cat > /etc/profile.d/klee.sh <<'EOF'
# KLEE symbolic execution engine (built against LLVM 16 with the STP solver).
# Same exports as the block in ~/.bashrc, for login shells and other shells
# that read /etc/profile.d but not ~/.bashrc.
export KLEE_INSTALL_PREFIX="/usr/local"
case ":${PATH}:" in
  *":/usr/local/bin:"*) ;;
  *) export PATH="/usr/local/bin${PATH:+:${PATH}}" ;;
esac
case ":${CPATH:-}:" in
  *":/usr/local/include:"*) ;;
  *) export CPATH="/usr/local/include${CPATH:+:${CPATH}}" ;;
esac
case ":${CPATH}:" in
  *":/usr/local/include/klee:"*) ;;
  *) export CPATH="${CPATH}:/usr/local/include/klee" ;;
esac
export KLEE_RUNTIME_LIBRARY_DIR="${KLEE_RUNTIME_LIBRARY_DIR:-/usr/local/lib/klee/runtime}"
case ":${LD_LIBRARY_PATH:-}:" in
  *":/usr/local/lib:"*) ;;
  *) export LD_LIBRARY_PATH="/usr/local/lib${LD_LIBRARY_PATH:+:${LD_LIBRARY_PATH}}" ;;
esac
EOF
chmod 644 /etc/profile.d/klee.sh
echo "=== login shell:"; env -i HOME=/root TERM=dumb bash -lc 'command -v klee; echo "CPATH=$CPATH"' 2>&1 | tail -3
echo "=== double-source idempotency:"; env -i HOME=/root PATH=/usr/bin:/bin bash -c 'source ~/.bashrc; . /etc/profile.d/klee.sh; source ~/.bashrc; echo "CPATH=$CPATH"; echo "PATH=$PATH"'

